@Tags(['slow'])
library;

import 'dart:async';
import 'dart:math';

import 'package:harbor/harbor.dart';
import 'package:rohd/rohd.dart';
import 'package:test/test.dart';

// Rectangular AV1 intra prediction (angle_delta=0, no edge filter,
// above-right/below-left as repeat), vs the software predictIntraRaw over all
// 13 modes and all 4 (have_above, have_left) combinations.
//
// First anchor: for bw==bh, HarborIntraPredRect must match the already-verified
// square HarborIntraPredAvail bit for bit. Then genuine rectangular sizes are
// checked against the SW golden directly.
void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  BigInt packB(List<int> b) {
    var v = BigInt.zero;
    for (var i = 0; i < b.length; i++) {
      v |= BigInt.from(b[i] & 0xff) << (i * 8);
    }
    return v;
  }

  List<int> unpack(BigInt pv, int n) => [
    for (var p = 0; p < n; p++) ((pv >> (p * 8)) & BigInt.from(0xff)).toInt(),
  ];

  for (final bs in [4, 8]) {
    test(
      'HarborIntraPredRect ${bs}x$bs == HarborIntraPredAvail (square anchor)',
      () async {
        final rect = HarborIntraPredRect(
          bw: bs,
          bh: bs,
          name: 'rect_anchor_$bs',
        );
        final sq = HarborIntraPredAvail(bs: bs, name: 'sq_anchor_$bs');
        final clk = SimpleClockGenerator(10).clk;

        final mode = Logic(name: 'mode', width: 4);
        final haveA = Logic(name: 'have_above');
        final haveL = Logic(name: 'have_left');
        final above = Logic(name: 'above', width: bs * 8);
        final left = Logic(name: 'left', width: bs * 8);
        final corner = Logic(name: 'above_left', width: 8);
        for (final t in [rect, sq]) {
          t.input('mode').srcConnection! <= mode;
          t.input('have_above').srcConnection! <= haveA;
          t.input('have_left').srcConnection! <= haveL;
          t.input('above').srcConnection! <= above;
          t.input('left').srcConnection! <= left;
          t.input('above_left').srcConnection! <= corner;
        }
        await rect.build();
        await sq.build();
        Simulator.setMaxSimTime(40000000);
        unawaited(Simulator.run());

        final rng = Random(0x5EC + bs);
        for (var iter = 0; iter < 30; iter++) {
          final av = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
          final lf = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
          final cr = rng.nextInt(256);
          for (var m = 0; m < 13; m++) {
            for (var av0 = 0; av0 < 2; av0++) {
              for (var lv0 = 0; lv0 < 2; lv0++) {
                mode.put(m);
                haveA.put(av0);
                haveL.put(lv0);
                above.put(packB(av));
                left.put(packB(lf));
                corner.put(cr);
                await clk.nextPosedge;
                final r = rect.output('pred').value.toBigInt();
                final s = sq.output('pred').value.toBigInt();
                expect(
                  r,
                  equals(s),
                  reason: 'bs=$bs mode=$m haveA=$av0 haveL=$lv0 iter=$iter',
                );
              }
            }
          }
        }
        await Simulator.endSimulation();
      },
    );
  }

  for (final size in const [
    [8, 4],
    [4, 8],
    [16, 8],
    [8, 16],
  ]) {
    final bw = size[0];
    final bh = size[1];
    test('HarborIntraPredRect ${bw}x$bh matches predictIntraRaw', () async {
      final t = HarborIntraPredRect(bw: bw, bh: bh);
      final clk = SimpleClockGenerator(10).clk;
      final mode = Logic(name: 'mode', width: 4);
      final haveA = Logic(name: 'have_above');
      final haveL = Logic(name: 'have_left');
      final above = Logic(name: 'above', width: bw * 8);
      final left = Logic(name: 'left', width: bh * 8);
      final corner = Logic(name: 'above_left', width: 8);
      t.input('mode').srcConnection! <= mode;
      t.input('have_above').srcConnection! <= haveA;
      t.input('have_left').srcConnection! <= haveL;
      t.input('above').srcConnection! <= above;
      t.input('left').srcConnection! <= left;
      t.input('above_left').srcConnection! <= corner;
      await t.build();
      Simulator.setMaxSimTime(60000000);
      unawaited(Simulator.run());

      final golden = bw == 8 && bh == 4
          ? _goldenRect8x4
          : bw == 4 && bh == 8
          ? _goldenRect4x8
          : bw == 16 && bh == 8
          ? _goldenRect16x8
          : _goldenRect8x16;
      var gi = 0;
      final rng = Random(0xBEEF + bw * 31 + bh);
      for (var iter = 0; iter < 25; iter++) {
        final av = [for (var i = 0; i < bw; i++) rng.nextInt(256)];
        final lf = [for (var i = 0; i < bh; i++) rng.nextInt(256)];
        final cr = rng.nextInt(256);
        for (var m = 0; m < 13; m++) {
          for (var av0 = 0; av0 < 2; av0++) {
            for (var lv0 = 0; lv0 < 2; lv0++) {
              mode.put(m);
              haveA.put(av0);
              haveL.put(lv0);
              above.put(packB(av));
              left.put(packB(lf));
              corner.put(cr);
              await clk.nextPosedge;

              final want = golden.sublist(gi * bw * bh, (gi + 1) * bw * bh);
              gi++;
              final got = unpack(t.output('pred').value.toBigInt(), bw * bh);
              expect(
                got,
                equals(want),
                reason:
                    'bw=$bw bh=$bh mode=$m haveA=$av0 haveL=$lv0 '
                    'iter=$iter',
              );
            }
          }
        }
      }
      await Simulator.endSimulation();
    });
  }
}

